import React from "react";
import styled from "styled-components";

// Contact form component with email functionality

const Container = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  z-index: 1;
  align-items: center;
  @media (max-width: 960px) {
    padding: 0px;
  }
`;

const Wrapper = styled.div`
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-direction: column;
  width: 100%;
  max-width: 1350px;
  padding: 0px 0px 80px 0px;
  gap: 12px;
  @media (max-width: 960px) {
    flex-direction: column;
  }
`;

const Title = styled.div`
  font-size: 42px;
  text-align: center;
  font-weight: 600;
  margin-top: 20px;
  color: ${({ theme }) => theme.text_primary};
  @media (max-width: 768px) {
    margin-top: 12px;
    font-size: 32px;
  }
`;

const Desc = styled.div`
  font-size: 18px;
  text-align: center;
  max-width: 600px;
  color: ${({ theme }) => theme.text_secondary};
  @media (max-width: 768px) {
    margin-top: 12px;
    font-size: 16px;
  }
`;


const Contact = () => {

  return (
    <Container id="contact">
      <Wrapper>
        <Title>Contact</Title>
        <Desc>
          Feel free to reach out to me for any questions or opportunities!
        </Desc>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            color: "white",
            marginBottom: "20px",
            cursor: "default",
            fontSize: "1.2rem",
          }}
        >
          <div style={{ marginTop: "10px", lineHeight: "1.6" }}>
            <div>
              <a
                href="tel:+917990873171"
                style={{ color: "white", textDecoration: "none" }}
              >
              📞{" "}
                +91 7990873171
              </a>
            </div>
            <div>
              <a
                href="mailto:ayushu031@gmail.com"
                style={{ color: "white", textDecoration: "none" }}
              >
                <svg xmlns="http://www.w3.org/2000/svg" height="16" width="16" fill="white" viewBox="0 0 24 24" style={{ marginRight: 6 }}>
                  <path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.89 2 1.99 2H20c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/>
                </svg>{" "}
                ayushu031@gmail.com
              </a>
            </div>
          </div>
        </div>
      </Wrapper>
    </Container>
  );
};

export default Contact;
